+const LOW: u64 = 2_000;
+/// Far above the fixture's full-fidelity mesh, still under the default.
+const RAISED: u64 = 5_000_000;
+
+fn models(n: &str) -> std::path::PathBuf {
+    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/models").join(n)
+}
